\draw[->,thick] (O) -- (B) node[midway,left] {$\underset{\sim}{b}$};
\draw (A) -- (B);
\fill (M) circle (2pt);
\node[below left] at (O) {$O$};
\node[right] at (A) {$A$};
\node[above] at (B) {$B$};
\node[above right] at (M) {$M$};
\end{tikzpicture}
[/tikz]

